            with urllib.request.urlopen(req, timeout=timeout) as r:
                data = json.loads(r.read().decode())
            if data.get('error'):
                raise Exception(data['error'])
            return data.get('result')
        except Exception as e:
            last_err = e
    raise last_err or Exception('No RPC endpoint available')


@app.route('/status')
def status():
    try:
        try:
            online = rpc_call('getHealth') == 'ok'
        except Exception:
            online = False
        slot = rpc_call('getSlot')
        nodes = rpc_call('getClusterNodes') or []
        ver = rpc_call('getVersion') or {}
        return jsonify({
            'status': 'online' if online else 'offline',
            'network': NETWORK,
            'current_slot': slot,
            'node_count': len(nodes),
            'version': ver.get('solana-core') if isinstance(ver, dict) else None,
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/block/<int:slot_number>')
def block(slot_number):
    try:
        res = rpc_call('getBlock', [slot_number, {'maxSupportedTransactionVersion': 0}])
        if res is None:
            return jsonify({'error': 'Block not found'}), 404
        return jsonify({
            'blockhash': res.get('blockhash'),
            'parent_slot': res.get('parentSlot'),
            'previous_blockhash': res.get('previousBlockhash'),
            'block_height': res.get('blockHeight'),
            'block_time': res.get('blockTime'),
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/transaction/<signature>')
def transaction(signature):
    try:
        res = rpc_call('getTransaction', [signature, {'encoding': 'json',
                                                       'maxSupportedTransactionVersion': 0}])
        if res is None:
            return jsonify({'error': 'Transaction not found'}), 404
        meta = res.get('meta') or {}
        tx = res.get('transaction') or {}
        message = (tx.get('transaction') or {}).get('message') or {}
        acct_keys = message.get('accountKeys') or []

        def addr(i):
            if i is None or i >= len(acct_keys):
                return None
            k = acct_keys[i]
            return k.get('pubkey') if isinstance(k, dict) else k

        def balances(lst):
            out = {}
            for b in (lst or []):
                amt = (b.get('uiTokenAmount') or {}).get('amount')
                out[(b['accountIndex'], b['mint'])] = int(amt) if amt is not None else 0
            return out

        pre = balances(meta.get('preTokenBalances'))
        post = balances(meta.get('postTokenBalances'))
        mints = set([m for (_, m) in list(pre.keys()) + list(post.keys())])
        transfers = []
        for m in mints:
            diffs = {}
            for (idx, mm), amt in pre.items():
                if mm == m:
                    diffs[idx] = diffs.get(idx, 0) - amt
            for (idx, mm), amt in post.items():
                if mm == m:
                    diffs[idx] = diffs.get(idx, 0) + amt
            senders = sorted([(idx, -d) for idx, d in diffs.items() if d < 0],
                             key=lambda x: -x[1])
            receivers = sorted([(idx, d) for idx, d in diffs.items() if d > 0],
                               key=lambda x: -x[1])
            si = 0
            for sidx, samt in senders:
                rem = samt
                while rem > 0 and si < len(receivers):
                    ridx, ramt = receivers[si]
                    take = min(rem, ramt)
                    transfers.append({'account': addr(sidx), 'mint': m, 'amount': take})
                    rem -= take
                    ramt -= take
                    if ramt <= 0:
                        si += 1
                    else:
                        receivers[si] = (ridx, ramt)
        return jsonify({
            'signature': signature,
            'slot': res.get('slot'),
            'block_time': res.get('blockTime'),
            'success': bool(meta.get('err') is None),
            'fee': meta.get('fee'),
            'token_transfers': transfers,
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/account/<address>')
def account(address):
    try:
        res = rpc_call('getAccountInfo', [address, {'encoding': 'jsonParsed'}])
        val = (res or {}).get('value')
        if val is None:
            return jsonify({'error': 'Account not found'}), 404
        return jsonify({
            'address': address,
            'executable': val.get('executable'),
            'lamports': val.get('lamports'),
            'owner': val.get('owner'),
            'rent_epoch': val.get('rentEpoch'),
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/program/<program_id>/accounts')
def program_accounts(program_id):
    try:
        try:
            limit = int(request.args.get('limit', 10))
        except Exception:
            limit = 10
        try:
            offset = int(request.args.get('offset', 0))
        except Exception:
            offset = 0
        if limit < 0:
            limit = 10
        if offset < 0:
            offset = 0
        params = [program_id, {'encoding': 'base64',
                               'dataSlice': {'offset': 0, 'length': 0},
                               'limit': 100000}]
        accounts = rpc_call('getProgramAccounts', params) or []
        total = len(accounts)
        page = accounts[offset: offset + limit]
        out = []
        for a in page:
            acc = a.get('account') or {}
            out.append({
                'pubkey': a.get('pubkey'),
                'account': {
                    'executable': acc.get('executable'),
                    'lamports': acc.get('lamports'),
                    'owner': acc.get('owner'),
                    'rent_epoch': acc.get('rentEpoch'),
                },
            })
        return jsonify({
            'program_id': program_id,
            'total_accounts': total,
            'limit': limit,
            'offset': offset,
            'accounts': out,
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
EOF
