            'parent_slot': res.get('parentSlot'),
            'previous_blockhash': res.get('previousBlockhash'),
            'block_height': res.get('blockHeight'),
            'block_time': res.get('blockTime'),
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


@app.route('/transaction/<signature>')
def transaction(signature):
    try:
        res = rpc_call('getTransaction', [signature, {'encoding': 'json',
                                                       'maxSupportedTransactionVersion': 0}])
        if res is None:
            return jsonify({'error': 'Transaction not found'}), 404
        meta = res.get('meta') or {}
        tx = res.get('transaction') or {}
        message = (tx.get('transaction') or {}).get('message') or {}
        acct_keys = message.get('accountKeys') or []

        def addr(i):
            if i is None or i >= len(acct_keys):
                return None
            k = acct_keys[i]
            return k.get('pubkey') if isinstance(k, dict) else k

        def balances(lst):
            out = {}
            for b in (lst or []):
                amt = (b.get('uiTokenAmount') or {}).get('amount')
                out[(b['accountIndex'], b['mint'])] = int(amt) if amt is not None else 0
            return out

        pre = balances(meta.get('preTokenBalances'))
        post = balances(meta.get('postTokenBalances'))
        mints = set([m for (_, m) in list(pre.keys()) + list(post.keys())])
        transfers = []
        for m in mints:
            diffs = {}
            for (idx, mm), amt in pre.items():
                if mm == m:
                    diffs[idx] = diffs.get(idx, 0) - amt
            for (idx, mm), amt in post.items():
                if mm == m:
                    diffs[idx] = diffs.get(idx, 0) + amt
            senders = sorted([(idx, -d) for idx, d in diffs.items() if d < 0],
                             key=lambda x: -x[1])
            receivers = sorted([(idx, d) for idx, d in diffs.items() if d > 0],
                               key=lambda x: -x[1])
            si = 0
            for sidx, samt in senders:
                rem = samt
                while rem > 0 and si < len(receivers):
                    ridx, ramt = receivers[si]
                    take = min(rem, ramt)
                    transfers.append({'account': addr(sidx), 'mint': m, 'amount': take})
                    rem -= take
                    ramt -= take
                    if ramt <= 0:
                        si += 1
                    else:
                        receivers[si] = (ridx, ramt)
        return jsonify({
            'signature': signature,
            'slot': res.get('slot'),
            'block_time': res.get('blockTime'),
            'success': bool(meta.get('err') is None),
            'fee': meta.get('fee'),
            'token_transfers': transfers,
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500


